use photocraft_engine::web_cmds::{WebSettings, optimize};
use photocraft_geom::Rect;
use serde_json::json;
use std::{error::Error, time::Instant};

fn main() -> Result<(), Box<dyn Error>> {
    let (width, height) = (6000usize, 4000usize);
    let pixels: Vec<_> = (0..height)
        .flat_map(|y| (0..width).map(move |x| [x as f32 / width as f32, 0.5 + ((x + y) as f32 * 0.002).sin() * 0.3, y as f32 / height as f32, 1.0]))
        .collect();
    let rect = Rect::new(0, 0, width as i32, height as i32);
    for format in ["gif", "png8"] {
        for run in 0..4 {
            let settings = WebSettings::from_params(&json!({"format": format, "colors": 128, "dither": "diffusion"}), "review")?;
            let start = Instant::now();
            let generated = optimize(&pixels, width, rect, &settings, None, None, None, 72.0, false)?;
            let generated_ms = start.elapsed().as_secs_f64() * 1000.0;
            println!(
                "{}",
                json!({"format": format, "path": "generated", "run": run, "warmup": run == 0, "ms": generated_ms, "bytes": generated.bytes.len(), "hash": blake3::hash(&generated.bytes).to_hex().to_string()})
            );
            let mut fixed = settings;
            fixed.color_table = Some(generated.color_table);
            fixed.color_table_edits.insert(0, [0, 255, 0]);
            let start = Instant::now();
            let edited = optimize(&pixels, width, rect, &fixed, None, None, None, 72.0, false)?;
            let fixed_ms = start.elapsed().as_secs_f64() * 1000.0;
            println!(
                "{}",
                json!({"format": format, "path": "legacy_table_edit", "run": run, "warmup": run == 0, "ms": fixed_ms, "bytes": edited.bytes.len(), "hash": blake3::hash(&edited.bytes).to_hex().to_string()})
            );
        }
    }
    Ok(())
}
